'use client';

import React, { useState } from 'react';

export default function VoiceScreen() {
  const [isSpeaking, setIsSpeaking] = useState(true);
  const [transcript, setTranscript] = useState(
    'Streaming 240ms turnaround... Whisper STT connected on 5 concurrent channels.'
  );

  const toggleVoice = () => {
    setIsSpeaking((prev) => !prev);
    const phrases = [
      'Customer query: "Book test drive for Sunday 11 AM in Gurugram." Auto-scheduled.',
      'VAD detected speech end in 120ms. LLM chunk response delivered.',
      'Neural TTS streaming synthesized audio frame #14 over WebSocket.',
      'Zero human handoff achieved across entire multi-turn support workflow.',
    ];
    setTranscript(phrases[Math.floor(Math.random() * phrases.length)]);
  };

  return (
    <div className="screen-panel-inner">
      <div style={{ marginBottom: '6px' }}>
        <span style={{ fontSize: '0.68rem', color: '#64748b', textTransform: 'uppercase', display: 'block' }}>
          FULL-DUPLEX WEBSOCKET VOICE AI
        </span>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.84rem', color: '#f8fafc', fontWeight: 600 }}>
          Whisper STT + Streaming Neural TTS
        </span>
      </div>

      <div className="voice-visualizer-container">
        <div className="voice-wave-bars">
          {[...Array(9)].map((_, i) => (
            <span
              key={i}
              className="voice-bar"
              style={{
                animationPlayState: isSpeaking ? 'running' : 'paused',
                opacity: isSpeaking ? 1 : 0.3,
              }}
            ></span>
          ))}
        </div>

        <div className="voice-stats-row">
          <span>⚡ Latency: &lt;400ms</span>
          <span>🎙️ 5 Concurrent Streams</span>
          <span>✨ 0 Human Handoff</span>
        </div>
      </div>

      <div className="terminal-stream-box" style={{ flex: 'none', height: '90px' }}>
        <div className="terminal-line">
          <span className="terminal-prompt" style={{ color: '#fbbf24' }}>voice://socket $</span>
          <span>stream --duplex=true --vad=active</span>
        </div>
        <div style={{ color: '#fbbf24', fontSize: '0.72rem', marginTop: '4px' }}>
          &gt; "{transcript}"
        </div>
        <div style={{ textAlign: 'right', marginTop: '6px' }}>
          <button
            onClick={toggleVoice}
            style={{
              padding: '3px 8px',
              fontSize: '0.68rem',
              background: 'rgba(245, 158, 11, 0.15)',
              border: '1px solid rgba(245, 158, 11, 0.3)',
              color: '#fbbf24',
              borderRadius: '6px',
              cursor: 'pointer',
              fontFamily: 'var(--font-mono)',
            }}
          >
            {isSpeaking ? '⏸ Pause Stream' : '▶ Speak / Prompt'}
          </button>
        </div>
      </div>
    </div>
  );
}
