'use client';

import React, { useState, useEffect } from 'react';
import { initAudio, setSoundEnabled, getSoundEnabled, playNodeActivate, playClick } from '../utils/sound';

export default function Navbar({ onOpenSearch }) {
  const [scrolled, setScrolled] = useState(false);
  const [sfxEnabled, setSfxEnabled] = useState(false);

  useEffect(() => {
    setSfxEnabled(getSoundEnabled());
    const handleScroll = () => {
      setScrolled(window.scrollY > 30);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 100,
        padding: scrolled ? '10px 24px' : '18px 24px',
        transition: 'all 0.25s ease',
        background: scrolled ? 'rgba(7, 9, 14, 0.85)' : 'rgba(7, 9, 14, 0.4)',
        backdropFilter: 'blur(16px)',
        WebkitBackdropFilter: 'blur(16px)',
        borderBottom: scrolled ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid transparent',
      }}
    >
      <div
        className="container-custom"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        {/* Brand Name & Role */}
        <a
          href="#hero"
          style={{
            textDecoration: 'none',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
          }}
        >
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontWeight: 700,
              fontSize: '0.88rem',
              letterSpacing: '0.06em',
              color: '#ffffff',
            }}
          >
            SHREYANS JAIN
          </span>
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.68rem',
              padding: '2px 8px',
              borderRadius: '9999px',
              background: 'rgba(56, 189, 248, 0.1)',
              color: '#38bdf8',
              border: '1px solid rgba(56, 189, 248, 0.25)',
              fontWeight: 500,
            }}
          >
            AI ARCHITECT
          </span>
        </a>

        {/* Center Streamlined Navigation Links */}
        <nav
          style={{
            display: 'none',
            gap: '24px',
            alignItems: 'center',
          }}
          className="desktop-nav"
        >
          <a href="#hero" className="nav-link">
            Overview
          </a>
          <a href="#act-systems" className="nav-link">
            Systems &amp; Impact
          </a>
          <a href="#act-journey" className="nav-link">
            Trajectory
          </a>
          <a href="#act-safety" className="nav-link">
            Observability
          </a>
          <a href="#act-contact" className="nav-link">
            Contact
          </a>
        </nav>

        {/* Right Action Tools */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          {/* Quick Search Cmd+K Trigger */}
          <button
            onClick={() => {
              playClick();
              if (onOpenSearch) onOpenSearch();
            }}
            className="nav-tool-btn"
            title="Search systems, roles, and tech stack (Cmd+K)"
          >
            <span>🔍</span>
            <span className="nav-tool-label">Search</span>
            <kbd className="nav-kbd">⌘K</kbd>
          </button>

          {/* Sound FX Toggle */}
          <button
            onClick={() => {
              const next = !sfxEnabled;
              setSfxEnabled(next);
              setSoundEnabled(next);
              if (next) {
                initAudio();
                playNodeActivate();
              }
            }}
            className={`nav-tool-btn ${sfxEnabled ? 'active-sfx' : ''}`}
            title={sfxEnabled ? 'Sound Enabled' : 'Sound Muted'}
          >
            <span>{sfxEnabled ? '🔊' : '🔇'}</span>
          </button>

          {/* CTA Button */}
          <a
            href="#act-contact"
            className="btn-primary"
            style={{
              padding: '7px 16px',
              fontSize: '0.82rem',
            }}
          >
            Connect →
          </a>
        </div>
      </div>

      <style jsx>{`
        .nav-link {
          color: var(--text-secondary);
          text-decoration: none;
          font-size: 0.84rem;
          font-weight: 500;
          transition: color 0.15s ease;
        }
        .nav-link:hover {
          color: #ffffff;
        }
        .nav-tool-btn {
          display: inline-flex;
          align-items: center;
          gap: 6px;
          padding: 6px 10px;
          border-radius: 8px;
          background: rgba(255, 255, 255, 0.04);
          border: 1px solid rgba(255, 255, 255, 0.08);
          color: var(--text-secondary);
          font-family: var(--font-mono);
          font-size: 0.76rem;
          cursor: pointer;
          transition: all 0.2s ease;
        }
        .nav-tool-btn:hover {
          background: rgba(255, 255, 255, 0.08);
          border-color: rgba(255, 255, 255, 0.16);
          color: #ffffff;
        }
        .nav-tool-btn.active-sfx {
          background: rgba(16, 185, 129, 0.12);
          border-color: rgba(16, 185, 129, 0.3);
          color: #34d399;
        }
        .nav-kbd {
          background: rgba(255, 255, 255, 0.08);
          padding: 1px 5px;
          border-radius: 4px;
          font-size: 0.65rem;
          border: 1px solid rgba(255, 255, 255, 0.12);
          color: #94a3b8;
        }
        @media (max-width: 600px) {
          .nav-tool-label {
            display: none;
          }
        }
        @media (min-width: 860px) {
          .desktop-nav {
            display: flex !important;
          }
        }
      `}</style>
    </header>
  );
}
