'use client';

import React, { useState } from 'react';

export default function RagScreen() {
  const [activeQuery, setActiveQuery] = useState('enterprise_sla_spec.pdf#page=42');
  const [similarity, setSimilarity] = useState(0.984);

  const simulateLookup = () => {
    const queries = [
      'enterprise_sla_spec.pdf#page=42 (98.4% match)',
      'flipkart_catalog_schema.json (99.1% match)',
      'multimodal_audio_spec.proto (97.8% match)',
      'guardrails_telemetry_v2.md (99.5% match)',
    ];
    const picked = queries[Math.floor(Math.random() * queries.length)];
    setActiveQuery(picked);
    setSimilarity(+(0.97 + Math.random() * 0.025).toFixed(3));
  };

  return (
    <div className="screen-panel-inner">
      <div className="rag-matrix-canvas">
        <div className="rag-flow-bar">
          <div>
            <span style={{ fontSize: '0.68rem', color: '#64748b', textTransform: 'uppercase', display: 'block' }}>
              HYBRID RETRIEVAL PIPELINE
            </span>
            <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.84rem', color: '#f8fafc', fontWeight: 600 }}>
              Dense Vector + BM25 Sparse Fusion
            </span>
          </div>
          <div className="rag-score-pill">
            ⚡ {(similarity * 100).toFixed(1)}% FAITHFULNESS
          </div>
        </div>

        <div className="rag-chunks-grid">
          <div className="rag-chunk-card">
            <div className="rag-chunk-title">Chunk #891 · Vector Space</div>
            <div className="rag-chunk-desc">
              Extracted SLA penalties from 200+ page enterprise RFP specification. Zero hallucination guarantee.
            </div>
          </div>
          <div className="rag-chunk-card">
            <div className="rag-chunk-title">Chunk #892 · Context Graph</div>
            <div className="rag-chunk-desc">
              Synthesizing cross-document citations across technical manuals in under 60 seconds.
            </div>
          </div>
        </div>

        <div className="terminal-stream-box" style={{ flex: 'none', height: '90px' }}>
          <div className="terminal-line">
            <span className="terminal-prompt">rag://vector-db $</span>
            <span>query --top_k=4 --hybrid=true</span>
          </div>
          <div style={{ color: '#34d399', fontSize: '0.72rem', marginTop: '4px' }}>
            &gt; Citation Resolved: {activeQuery}
          </div>
          <div style={{ textAlign: 'right', marginTop: '6px' }}>
            <button
              onClick={simulateLookup}
              style={{
                padding: '3px 8px',
                fontSize: '0.68rem',
                background: 'rgba(16, 185, 129, 0.15)',
                border: '1px solid rgba(16, 185, 129, 0.3)',
                color: '#34d399',
                borderRadius: '6px',
                cursor: 'pointer',
                fontFamily: 'var(--font-mono)',
              }}
            >
              🔍 Query Next Chunk
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
